const $ = id => document.getElementById(id);
const t = key => key.startsWith("po_") ? purchaseOrdersView().t(key.slice(3)) : translations[currentLanguage]?.[key] ?? translations.de[key] ?? key;
const locale = () => currentLanguage === "en" ? "en-US" : "de-DE";
const activeCurrency = () => currencyRates[currentCurrency] || currencyRates.EUR;
const activeCurrencySymbol = () => currencySymbols[activeCurrency().code] || activeCurrency().code;

function numericDefinition(key = "", fallbackType = "number") {
  return inventoryFieldDefinitions[key] || { type: fallbackType, fieldKey: key };
}

function rowNumericParseResult(row, key) {
  const result = row?.__numericParseResults?.[key] || null;
  if (result?.status === "missing" && typeof row?.[key] === "number" && Number.isFinite(row[key])) {
    return null;
  }
  return result;
}

function numericValueEvidence(value, key = "", options = {}) {
  return numericEvidence(value, {
    fieldKey: key,
    fieldDefinition: numericDefinition(key, options.type || "number"),
    localeProfile: options.localeProfile || {},
    parseResult: options.parseResult || null
  });
}

function finiteNumericValue(value, key = "", options = {}) {
  const evidence = numericValueEvidence(value, key, options);
  return evidence.status === "valid" ? evidence.normalizedValue : null;
}

function numericAggregate(data, key, options = {}) {
  const rows = Array.isArray(data) ? data : [];
  return aggregateNumericValues(rows, {
    fieldKey: key,
    fieldDefinition: numericDefinition(key, options.type || "number"),
    localeProfile: options.localeProfile || numericLocaleProfileForRows(rows, key),
    valueAccessor: row => row?.[key],
    parseResultAccessor: row => rowNumericParseResult(row, key),
    allowPartial: options.allowPartial === true
  });
}

function formatNumber(value, options = {}, key = "") {
  const normalized = finiteNumericValue(value, key);
  return normalized === null ? t("notAvailable") : normalized.toLocaleString(locale(), options);
}

const formatCount = value => formatNumber(value);

function convertMoneyValue(value, key = "", options = {}) {
  const normalized = finiteNumericValue(value, key, { ...options, type: "currency" });
  if (normalized === null) return null;
  const converted = normalized * activeCurrency().rate;
  return Number.isFinite(converted) ? (converted === 0 ? 0 : converted) : null;
}

function money(value, key = "", options = {}) {
  const converted = convertMoneyValue(value, key, options);
  return converted === null
    ? t("notAvailable")
    : `${Math.round(converted).toLocaleString(locale())} ${activeCurrency().code}`;
}

function formatExactKpiMoney(value) {
  if (typeof value !== "number" || !Number.isFinite(value)) return t("notAvailable");
  return new Intl.NumberFormat(locale(), {
    style: "currency",
    currency: "EUR",
    currencyDisplay: "symbol",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(value === 0 ? 0 : value);
}

function readNavCollapsedPreference() {
  try {
    return localStorage.getItem(NAV_COLLAPSED_STORAGE_KEY) === "true";
  } catch (error) {
    return false;
  }
}

function shouldUseCompactNavigation() {
  return window.matchMedia("(max-width: 1099px)").matches;
}

function updateNavigationSummary() {
  const nav = document.querySelector(".main-nav");
  const activeTab = document.querySelector(".process-tabs button.active");
  const label = activeTab?.textContent?.trim() || activeProcessLabel || t("navOverview");
  activeProcessLabel = label;
  const currentSection = $("currentSectionLabel");
  if (currentSection) currentSection.textContent = label;

  const toggle = $("navToggleButton");
  if (!toggle) return;

  const collapsed = nav?.classList.contains("collapsed");
  const labelTarget = toggle.querySelector("[data-i18n='navSections']");
  if (labelTarget) labelTarget.textContent = t("navSections");
  else toggle.textContent = t("navSections");
  toggle.classList.toggle("nav-collapsed", Boolean(collapsed));
  toggle.classList.toggle("sections-open", Boolean(activeSectionsPopover));
  toggle.setAttribute("aria-label", collapsed ? t("navShowSections") : t("navCollapse"));
  toggle.setAttribute("title", collapsed ? t("navShowSections") : t("navCollapse"));
  toggle.setAttribute("aria-expanded", String(Boolean(activeSectionsPopover)));
}

function setNavigationCollapsed(collapsed, options = {}) {
  const nav = document.querySelector(".main-nav");
  if (!nav) return;

  const useCompactNavigation = shouldUseCompactNavigation();
  const nextCollapsed = useCompactNavigation ? true : false;
  closeSectionsPopover();
  nav.classList.toggle("collapsed", nextCollapsed);
  if (options.persist !== false && useCompactNavigation) {
    try {
      localStorage.setItem(NAV_COLLAPSED_STORAGE_KEY, String(nextCollapsed));
    } catch (error) {
      // Local storage can be unavailable for file-based prototypes in strict browser modes.
    }
  }
  updateNavigationSummary();
}

function initNavigationCollapse() {
  setNavigationCollapsed(shouldUseCompactNavigation() ? readNavCollapsedPreference() : false, { persist: false });
  window.addEventListener("resize", () => {
    setNavigationCollapsed(shouldUseCompactNavigation() ? readNavCollapsedPreference() : false, { persist: false });
  });
}

function closeSectionsPopover(options = {}) {
  const trigger = activeSectionsPopoverTrigger;
  if (activeSectionsPopover) {
    activeSectionsPopover.remove();
    activeSectionsPopover = null;
  }
  activeSectionsPopoverTrigger = null;
  const toggle = $("navToggleButton");
  if (toggle) {
    toggle.classList.remove("sections-open");
    toggle.setAttribute("aria-expanded", "false");
    toggle.removeAttribute("aria-controls");
  }
  if (options.restoreFocus) trigger?.focus({ preventScroll: true });
}

function positionSectionsPopover(popover, trigger) {
  const rect = trigger.getBoundingClientRect();
  const width = popover.offsetWidth || 256;
  const left = Math.min(
    rect.left,
    window.innerWidth - width - 12
  );
  popover.style.left = `${Math.max(12, left)}px`;
  popover.style.top = `${Math.min(window.innerHeight - 12, rect.bottom + 8)}px`;
}

function focusSectionsPopoverItem(popover, index) {
  const items = [...popover.querySelectorAll("[role='menuitem']")];
  if (!items.length) return;
  const normalizedIndex = (index + items.length) % items.length;
  items.forEach((item, itemIndex) => item.tabIndex = itemIndex === normalizedIndex ? 0 : -1);
  items[normalizedIndex].focus({ preventScroll: true });
}

function handleSectionsPopoverKeydown(event) {
  const popover = event.currentTarget;
  const items = [...popover.querySelectorAll("[role='menuitem']")];
  const currentIndex = Math.max(0, items.indexOf(event.target.closest?.("[role='menuitem']")));
  if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
    event.preventDefault();
    const targetIndex = event.key === "Home"
      ? 0
      : event.key === "End"
        ? items.length - 1
        : currentIndex + (event.key === "ArrowDown" ? 1 : -1);
    focusSectionsPopoverItem(popover, targetIndex);
    return;
  }
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    closeSectionsPopover({ restoreFocus: true });
    updateNavigationSummary();
    return;
  }
  if (event.key === "Tab") {
    const trigger = activeSectionsPopoverTrigger;
    const focusable = focusableElementsIn(document.body).filter(element => !popover.contains(element));
    const triggerIndex = Math.max(0, focusable.indexOf(trigger));
    const targetIndex = event.shiftKey
      ? (triggerIndex - 1 + focusable.length) % focusable.length
      : (triggerIndex + 1) % focusable.length;
    event.preventDefault();
    closeSectionsPopover();
    focusable[targetIndex]?.focus({ preventScroll: true });
    updateNavigationSummary();
  }
}

function openSectionsPopover(trigger) {
  closeSectionsPopover();
  const tabs = [...document.querySelectorAll(".process-tabs button")];
  const popover = document.createElement("div");
  popover.id = "sectionsPopover";
  popover.className = "sections-popover";
  popover.setAttribute("role", "menu");
  popover.setAttribute("aria-label", t("navSections"));
  popover.innerHTML = `
    <div class="sections-popover-list">
      ${tabs.map(tab => `
        <button type="button" role="menuitem" tabindex="-1" class="${tab.classList.contains("active") ? "active" : ""}"
          ${tab.classList.contains("active") ? 'aria-current="page"' : ""}
          data-nav-section="${html(tab.dataset.process)}">${html(tab.textContent.trim())}</button>
      `).join("")}
    </div>
  `;
  popover.addEventListener("keydown", handleSectionsPopoverKeydown);
  document.body.appendChild(popover);
  window.ObsoliQIcons?.enhanceShell(popover);
  activeSectionsPopover = popover;
  activeSectionsPopoverTrigger = trigger;
  positionSectionsPopover(popover, trigger);
  trigger.classList.add("sections-open");
  trigger.setAttribute("aria-expanded", "true");
  trigger.setAttribute("aria-controls", popover.id);
  const activeIndex = Math.max(0, tabs.findIndex(tab => tab.classList.contains("active")));
  focusSectionsPopoverItem(popover, activeIndex);
}

function handleNavigationControl(event) {
  event.preventDefault();
  event.stopPropagation();
  if (!shouldUseCompactNavigation()) {
    setNavigationCollapsed(false, { persist: false });
    return;
  }
  const nav = document.querySelector(".main-nav");
  const collapsed = nav?.classList.contains("collapsed");
  if (!collapsed) {
    setNavigationCollapsed(true);
    return;
  }
  if (activeSectionsPopover) {
    closeSectionsPopover();
    updateNavigationSummary();
  } else {
    openSectionsPopover(event.currentTarget);
    updateNavigationSummary();
  }
}

function advancedFilterStorageKey(scope) {
  return `${ADVANCED_FILTER_STORAGE_PREFIX}.${scope}`;
}

function readAdvancedFiltersOpen(scope, defaultOpen = false) {
  try {
    const value = localStorage.getItem(advancedFilterStorageKey(scope));
    return value === null ? defaultOpen : value === "true";
  } catch (error) {
    return defaultOpen;
  }
}

function setAdvancedFiltersOpen(scope, isOpen) {
  try {
    localStorage.setItem(advancedFilterStorageKey(scope), String(Boolean(isOpen)));
  } catch (error) {
    // Local storage is optional in this local prototype.
  }
}

function formatCompactMoney(value, options = {}) {
  // Exact KPI presentations stay on their validated EUR source basis; other views retain display FX.
  const converted = options.sourceEuro ? finiteNumericValue(value) : convertMoneyValue(value);
  if (converted === null) return t("notAvailable");
  const absolute = Math.abs(converted);
  const symbol = options.sourceEuro ? "€" : activeCurrencySymbol();
  const german = currentLanguage === "de";
  const number = (amount, maximumFractionDigits) => amount.toLocaleString(locale(), {
    minimumFractionDigits: 0,
    maximumFractionDigits
  });

  if (absolute >= 1000000) {
    const compact = number(converted / 1000000, 2);
    return german ? `${compact} Mio. ${symbol}` : `${symbol}${compact}M`;
  }
  if (absolute >= 10000) {
    const thousands = converted / 1000;
    const digits = Math.abs(thousands) >= 100 ? 0 : 1;
    const compact = number(thousands, digits);
    return german ? `${compact} Tsd. ${symbol}` : `${symbol}${compact}k`;
  }
  const full = Math.round(converted).toLocaleString(locale());
  return german ? `${full} ${symbol}` : `${symbol}${full}`;
}

function setMoneyMetric(id, value) {
  const target = $(id);
  if (!target) return;
  target.textContent = formatCompactMoney(value);
  target.title = money(value);
  target.classList.toggle("metric-value-unavailable", finiteNumericValue(value) === null);
}
