  if (obsoliqTestMode) dataQualityRenderCount += 1;
  const dataQualityRows = getDataQualityRows();
  updateVisibleDatasetChipsForView("check", dataQualityRows.length);
  $("dataCheck").innerHTML = renderDataCheck(dataQualityRows);
