function handleFilterControlEvent(event) {
  const target = event.target;
  if (!(target instanceof HTMLElement)) return;
  if (target.classList.contains("column-filter-popover-search")) {
    filterPopoverOptions(target);
    return;
  }
  if (target.classList.contains("column-filter-control")) {
    setColumnFilterValue(target.dataset.columnScope, target.dataset.columnKey, target.value);
    renderCurrentView();
    return;
  }
  if (target.classList.contains("data-quality-column-filter")) {
    updateDataQualityFilterState(target.dataset.qualityFilter, target.value);
    renderDataQuality();
    return;
  }
  if (target.classList.contains("remediation-filter-control")) {
    updateFilterStateFromControls();
    const immediate = event.type === "change" || target.tagName === "SELECT";
    scheduleRemediationFilterResults({ immediate });
    return;
  }
  if (target.classList.contains("remediation-correction-control")) {
    if (target.id === "remediationTargetField" || target.id === "remediationResolutionMethod" || target.id === "remediationMasterMode") {
      refreshRemediationTargetDependentControls(selectedRemediationField());
    }
    const issue = dataQualityIssues.find(item => item.issueId === activeRemediationIssueId);
    if (issue) updateRemediationApplyState(issue);
    const immediate = event.type === "change"
      || target.tagName === "SELECT"
      || ["checkbox", "radio"].includes(String(target.type || ""));
    scheduleRemediationPreviewUpdate({ immediate });
    return;
  }
  if (target.classList.contains("live-filter-control")) {
    renderCurrentView();
  }
}

function setInventoryTableHeight(height) {
  const min = 280;
  const max = Math.max(min, Math.round(window.innerHeight * 0.75));
  const next = Math.min(max, Math.max(min, Math.round(height)));
  document.documentElement.style.setProperty("--inventory-table-height", `${next}px`);
  try {
    localStorage.setItem("obsoliqInventoryTableHeight", String(next));
  } catch {
    // Local storage is optional for the prototype.
  }
}

function initInventoryTableResize() {
  const handle = document.getElementById("inventoryResizeHandle");
  const table = document.getElementById("inventoryTable");
  if (!handle || !table) return;

  try {
    const saved = Number(localStorage.getItem("obsoliqInventoryTableHeight"));
    if (Number.isFinite(saved) && saved > 0) setInventoryTableHeight(saved);
  } catch {
    // Ignore unavailable storage.
  }

  let dragState = null;

  handle.addEventListener("pointerdown", event => {
    dragState = {
      startY: event.clientY,
      startHeight: table.getBoundingClientRect().height || 520
    };
    handle.classList.add("dragging");
    document.body.classList.add("resizing-table");
    handle.setPointerCapture?.(event.pointerId);
    event.preventDefault();
  });

  window.addEventListener("pointermove", event => {
    if (!dragState) return;
    setInventoryTableHeight(dragState.startHeight + event.clientY - dragState.startY);
  });

  window.addEventListener("pointerup", () => {
    if (!dragState) return;
    dragState = null;
    handle.classList.remove("dragging");
    document.body.classList.remove("resizing-table");
  });

  handle.addEventListener("keydown", event => {
    if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
    const current = table.getBoundingClientRect().height || 520;
    if (event.key === "ArrowUp") setInventoryTableHeight(current - 32);
    if (event.key === "ArrowDown") setInventoryTableHeight(current + 32);
    if (event.key === "Home") setInventoryTableHeight(280);
    if (event.key === "End") setInventoryTableHeight(window.innerHeight * 0.75);
    event.preventDefault();
  });
}

function runDownload() {
  if (dataOperationInProgress()) return;
  try {
    pendingDownloadScope = selectedDownloadScope();
    pendingDownloadVariant = selectedDownloadVariant();
    const format = selectedDownloadFormat();
    closeDownloadDialog();
    setBusy(true, t("exportCreating"));
    const payload = buildDownloadPayload(pendingDownloadType, format, pendingDownloadScope);
    if (payload) downloadBlob(payload.blob, payload.filename);
  } catch (error) {
    setFeedback(t("downloadFailed"), "error");
    alert(error.message);
  } finally {
    setBusy(false);
  }
}

let dataFoundationDisclosureControllerInitialized = false;
let lastDataFoundationSummaryControl = null;
let dataFoundationModeQuery = null;

function isDataFoundationMobileMode() {
  return dataFoundationModeQuery ? dataFoundationModeQuery.matches : window.innerWidth < 900;
}

function focusableElementsIn(container) {
  if (!container) return [];
  return [...container.querySelectorAll([
    "button:not([disabled])",
    "a[href]",
    "input:not([disabled])",
    "select:not([disabled])",
    "textarea:not([disabled])",
    "summary",
    "[tabindex]:not([tabindex='-1'])"
  ].join(","))].filter(element => element.offsetParent !== null || element === document.activeElement);
}

function focusDataFoundationDetail(details) {
  const detail = details?.querySelector(".data-foundation-detail");
  const firstFocusable = focusableElementsIn(detail)[0];
  (firstFocusable || detail)?.focus?.({ preventScroll: true });
}

function updateDataFoundationInteractionMode(options = {}) {
  const isMobile = isDataFoundationMobileMode();
  const openDetails = document.querySelector("[data-data-foundation][open]");
  document.querySelectorAll("[data-data-foundation]").forEach(details => {
    details.dataset.dataFoundationMode = isMobile ? "drawer" : "popover";
    const detail = details.querySelector(".data-foundation-detail");
    if (!detail) return;
    if (isMobile) {
      detail.setAttribute("role", "dialog");
      detail.setAttribute("aria-modal", "true");
      detail.setAttribute("tabindex", "-1");
    } else {
      detail.setAttribute("role", "region");
      detail.removeAttribute("aria-modal");
      detail.removeAttribute("tabindex");
    }
  });
  document.body.classList.toggle("data-foundation-modal-open", Boolean(openDetails && isMobile));
  if (openDetails && isMobile && options.focus !== false && !openDetails.contains(document.activeElement)) {
    focusDataFoundationDetail(openDetails);
  }
}

function syncDataFoundationDisclosureState() {
  document.querySelectorAll("[data-data-foundation]").forEach(details => {
    const summary = details.querySelector(":scope > summary");
    if (summary) summary.setAttribute("aria-expanded", details.open ? "true" : "false");
  });
  updateDataFoundationInteractionMode({ focus: false });
}

function closeDataFoundationDetail(options = {}) {
  let closed = false;
  document.querySelectorAll("[data-data-foundation][open]").forEach(details => {
    details.removeAttribute("open");
    closed = true;
  });
  if (closed) syncDataFoundationDisclosureState();
  if (closed) document.body.classList.remove("data-foundation-modal-open");
  if (closed && options.focus !== false) {
    (lastDataFoundationSummaryControl || document.querySelector("[data-data-foundation] > summary"))?.focus?.({ preventScroll: true });
  }
  return closed;
}

function initDataFoundationDisclosureController() {
  if (dataFoundationDisclosureControllerInitialized) return;
  dataFoundationDisclosureControllerInitialized = true;
  dataFoundationModeQuery = window.matchMedia("(max-width: 899px)");
  document.addEventListener("click", event => {
    if (!(event.target instanceof Element)) return;
    const reviewButton = event.target.closest("[data-df-review]");
    if (reviewButton) {
      const details = document.getElementById(`df-review-${reviewButton.dataset.dfReview}`);
      if (details) {
        details.open = true;
        details.querySelector("summary")?.focus({ preventScroll: true });
        details.scrollIntoView({ block: "nearest" });
      }
      return;
    }
    if (event.target.closest("[data-df-history-review]")) {
      const detail = document.getElementById("df-history-review");
      detail?.focus({ preventScroll: true });
      detail?.scrollIntoView({ block: "nearest" });
      return;
    }
    if (event.target.closest("[data-df-po-open]")) {
      closeDataFoundationDetail({ focus: false });
      switchProcessTab("purchase-orders");
      const heading = document.querySelector('#purchaseOrdersPage h2');
      if (heading) { heading.tabIndex = -1; heading.focus({ preventScroll: true }); }
      return;
    }
    if (event.target.closest("[data-data-foundation] [data-po-import]")) {
      closeDataFoundationDetail({ focus: false });
      return;
    }
    const closeButton = event.target.closest("[data-data-foundation-close]");
    if (closeButton) {
      event.preventDefault();
      closeDataFoundationDetail();
      return;
    }
    const retryButton = event.target.closest("[data-data-foundation-retry-history]");
    if (retryButton) {
      event.preventDefault();
      retryHistoricalMetricsRuntime();
      return;
    }
    const summary = event.target.closest("[data-data-foundation] > summary");
    if (summary) {
      lastDataFoundationSummaryControl = summary;
      setTimeout(() => {
        syncDataFoundationDisclosureState();
        const details = summary.closest("[data-data-foundation]");
        if (details?.open && isDataFoundationMobileMode()) focusDataFoundationDetail(details);
      }, 0);
      return;
    }
    const openPanel = document.querySelector("[data-data-foundation][open]");
    if (openPanel && !isDataFoundationMobileMode() && !event.target.closest("[data-data-foundation]")) {
      closeDataFoundationDetail({ focus: false });
    }
  });
  window.addEventListener("keydown", event => {
    if (event.key === "Escape" && closeDataFoundationDetail()) {
      event.preventDefault();
      return;
    }
    if (event.key !== "Tab" || !isDataFoundationMobileMode()) return;
    const openPanel = document.querySelector("[data-data-foundation][open]");
    const detail = openPanel?.querySelector(".data-foundation-detail");
    if (!detail) return;
    const focusable = focusableElementsIn(detail);
    if (!focusable.length) {
      event.preventDefault();
      detail.focus?.({ preventScroll: true });
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  });
  document.addEventListener("toggle", event => {
    if (!(event.target instanceof HTMLDetailsElement) || !event.target.matches("[data-data-foundation]")) return;
    syncDataFoundationDisclosureState();
    if (event.target.open && isDataFoundationMobileMode()) focusDataFoundationDetail(event.target);
  }, true);
  const modeChangeHandler = () => updateDataFoundationInteractionMode({ focus: false });
  if (dataFoundationModeQuery.addEventListener) dataFoundationModeQuery.addEventListener("change", modeChangeHandler);
  else dataFoundationModeQuery.addListener(modeChangeHandler);
  window.addEventListener("resize", modeChangeHandler, { passive: true });
  syncDataFoundationDisclosureState();
}

function addEventListenerIfPresent(id, eventName, handler, options = {}) {
  const element = $(id);
  if (!element) {
    if (!options.silent) console.warn(`[ObsoliQ] Optional UI element missing for event registration: #${id}`);
    return false;
  }
  element.addEventListener(eventName, handler);
  return true;
}

function warnMissingMappingAssistantElements() {
  const missing = mappingAssistantRequiredElementIds.filter(id => !$(id));
  if (missing.length) {
    console.warn(`[ObsoliQ] Mapping Assistant integration warning: missing element IDs: ${missing.join(", ")}`);
  }
}

